def f(n):
    def factorial(i):
        if i == 0 or i == 1:
            return 1
        result = 1
        for j in range(2, i + 1):
            result *= j
        return result

    def sum_to_i(i):
        return i * (i + 1) // 2

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_i(i))
    return result
```

