        else:
            # To calculate tri(n) for odd n, we need tri(n+1) which is not yet calculated
            # We will append a placeholder and update it later
            sequence.append(0)
            sequence[i - 1] = sequence[i - 2] + sequence[i - 3] + sequence[i]
            sequence[i] = sequence[i - 1] + sequence[i - 2] + sequence[i - 3]

    return sequence[:n + 1]
