        return []

    # Initialize the list with the base case
    sequence = [1] * (n + 1)
    if n >= 1:
        sequence[1] = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            sequence[i] = 1 + i // 2
        else:
            # To calculate tri(n) for odd n, we need tri(n + 1) which is not yet calculated
            # We will calculate it first if it's within bounds
            if i + 1 > n:
                # If n + 1 is out of bounds, we calculate it as if it were in bounds
                next_value = 1 + (i + 1) // 2
            else:
                next_value = sequence[i + 1]
            sequence[i] = sequence[i - 1] + sequence[i - 2] + next_value

    return sequence
