def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    # Sort words first by lexicographical order, then by unique character count in descending order
    sorted_words = sorted(words, key=lambda x: (unique_char_count(x), -ord(min(x))))
    sorted_words.sort(key=unique_char_count, reverse=True)

    return sorted_words[0] if sorted_words else ""
```

