    def unique_char_count(word):
        return len(set(word))

    # Sort words first by unique character count in descending order, then by lexicographical order
    sorted_words = sorted(words, key=lambda x: (-unique_char_count(x), x))

    return sorted_words[0] if sorted_words else ""
