def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    # Sort words first by the number of unique characters (descending),
    # then lexicographically (ascending)
    sorted_words = sorted(words, key=lambda word: (-unique_char_count(word), word))

    # Return the first word from the sorted list
    return sorted_words[0] if sorted_words else ""
